CREATE OR REPLACE FUNCTION public.consume_resident_auth_limit(p_key text, p_limit integer, p_window integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF p_limit < 1 OR p_window < 1 OR p_window > 86400 OR length(p_key) <> 64 THEN RETURN false; END IF; DELETE FROM public.resident_auth_limits WHERE key_hash IN (SELECT key_hash FROM public.resident_auth_limits WHERE window_start < now() - interval '1 day' LIMIT 100); INSERT INTO public.resident_auth_limits(key_hash) VALUES(p_key) ON CONFLICT(key_hash) DO UPDATE SET attempts=CASE WHEN resident_auth_limits.window_start < now()-make_interval(secs=>p_window) THEN 1 ELSE least(resident_auth_limits.attempts+1,p_limit+1) END, window_start=CASE WHEN resident_auth_limits.window_start < now()-make_interval(secs=>p_window) THEN now() ELSE resident_auth_limits.window_start END RETURNING attempts INTO n; RETURN n <= p_limit; END $$; REVOKE ALL ON FUNCTION public.consume_resident_auth_limit(text,integer,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_resident_auth_limit(text,integer,integer) TO service_role;